import PropTypes from 'prop-types';
import { styled, useTheme } from '@mui/material/styles';
import { Avatar, Box, List, ListItem, ListItemAvatar, ListItemText, Typography } from '@mui/material';

// Social Media Icons
import {
    Facebook as FacebookIcon,
    Twitter as TwitterIcon,
    Instagram as InstagramIcon,
    LinkedIn as LinkedInIcon,
    YouTube as YouTubeIcon,
    Pinterest as PinterestIcon
} from '@mui/icons-material';

// project imports
import MainCard from 'ui-component/cards/MainCard';
import TotalIncomeCard from 'ui-component/cards/Skeleton/TotalIncomeCard';

// styles
const CardWrapper = styled(MainCard)(({ theme, bgcolor }) => ({
    backgroundColor: bgcolor || theme.palette.primary.dark,
    color: theme.palette.primary.light,
    overflow: 'hidden',
    position: 'relative',
    '&:after': {
        content: '""',
        position: 'absolute',
        width: 210,
        height: 210,
        borderRadius: '50%',
        top: -30,
        right: -180,
        background: 'rgba(255, 255, 255, 0.1)'
    },
    '&:before': {
        content: '""',
        position: 'absolute',
        width: 210,
        height: 210,
        borderRadius: '50%',
        top: -160,
        right: -130,
        background: 'rgba(255, 255, 255, 0.1)'
    }
}));

// Social media data mapping
const socialMediaIcons = {
    facebook: <FacebookIcon />,
    twitter: <TwitterIcon />,
    instagram: <InstagramIcon />,
    linkedin: <LinkedInIcon />,
    youtube: <YouTubeIcon />,
    pinterest: <PinterestIcon />,
    youtube1: <YouTubeIcon />,
    pinterest1: <PinterestIcon />
};

const socialMediaColors = {
    facebook: '#1877F2',
    twitter: '#1DA1F2',
    instagram: '#E1306C',
    linkedin: '#0077B5',
    youtube: '#FF0000',
    pinterest: '#E60023',
    youtube1: '#FF0000',
    pinterest1: '#E60023'
};

// ==============================|| DYNAMIC SOCIAL STAT CARD ||============================== //

const TotalIncomeDarkCard = ({ isLoading, platform, title, value }) => {
    const theme = useTheme();
    const icon = socialMediaIcons[platform] || socialMediaIcons.facebook;
    const bgcolor = socialMediaColors[platform] || socialMediaColors.facebook;

    return (
        <>
            {isLoading ? (
                <TotalIncomeCard />
            ) : (
                <CardWrapper border={false} content={false} bgcolor={bgcolor}>
                    <Box sx={{ p: 3 }}>
                        <List sx={{ py: 0 }}>
                            <ListItem alignItems="center" disableGutters sx={{ py: 0 }}>
                                <ListItemAvatar>
                                    <Avatar
                                        variant="rounded"
                                        sx={{
                                            ...theme.typography.commonAvatar,
                                            ...theme.typography.largeAvatar,
                                            backgroundColor: 'rgba(0, 0, 0, 0.2)',
                                            color: '#fff'
                                        }}
                                    >
                                        {icon}
                                    </Avatar>
                                </ListItemAvatar>
                                <ListItemText
                                    sx={{
                                        py: 0,
                                        mt: 0.45,
                                        mb: 0.45
                                    }}
                                    primary={
                                        <Typography variant="h4" sx={{ color: '#fff' }}>
                                            {value}
                                        </Typography>
                                    }
                                    secondary={
                                        <Typography variant="subtitle2" sx={{ color: 'rgba(255, 255, 255, 0.7)', mt: 0.25 }}>
                                            {title}
                                        </Typography>
                                    }
                                />
                            </ListItem>
                        </List>
                    </Box>
                </CardWrapper>
            )}
        </>
    );
};

TotalIncomeDarkCard.propTypes = {
    isLoading: PropTypes.bool,
    platform: PropTypes.oneOf(['facebook', 'twitter', 'instagram', 'linkedin', 'youtube', 'pinterest', 'youtube1', 'pinterest1'])
        .isRequired,
    title: PropTypes.string.isRequired,
    value: PropTypes.string.isRequired
};

TotalIncomeDarkCard.defaultProps = {
    isLoading: false
};

export default TotalIncomeDarkCard;
