import PropTypes from 'prop-types';
import { useTheme } from '@mui/material/styles';
import { Card, CardContent, Grid, Typography, useMediaQuery, Box, Link } from '@mui/material';
import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { textAlign } from '@mui/system';
import { ArrowForward } from '@mui/icons-material';

const RevenueCard = ({ primary, secondary, content, iconPrimary, color, colorBottom }) => {
    const theme = useTheme();
    const matchDownXs = useMediaQuery(theme.breakpoints.down('sm'));

    // Handle both component and JSX element cases
    const renderIcon = () => {
        if (!iconPrimary) return null;

        if (React.isValidElement(iconPrimary)) {
            // If it's already a JSX element, clone it to add props
            return React.cloneElement(iconPrimary, {
                fontSize: 'large',
                sx: {
                    width: matchDownXs ? 70 : 90,
                    height: matchDownXs ? 70 : 90,
                    opacity: 0.5,
                    color: 'inherit'
                }
            });
        }

        // If it's a component, create an element
        const IconComponent = iconPrimary;
        return (
            <IconComponent
                fontSize="large"
                sx={{
                    width: matchDownXs ? 70 : 90,
                    height: matchDownXs ? 70 : 90,
                    opacity: 0.5,
                    color: 'inherit'
                }}
            />
        );
    };

    return (
        <Card
            sx={{
                background: color,
                position: 'relative',
                color: '#fff',
                height: '100%'
            }}
        >
            <CardContent>
                <Typography
                    variant="body2"
                    sx={{
                        position: 'absolute',
                        right: 13,
                        top: 14,
                        color: '#fff',
                        [theme.breakpoints.down('sm')]: {
                            top: 13
                        }
                    }}
                >
                    {renderIcon()}
                </Typography>
                <Grid container direction={matchDownXs ? 'column' : 'row'} spacing={1}>
                    <Grid item xs={12}>
                        <Typography variant="h1" color="inherit">
                            {secondary}
                        </Typography>
                    </Grid>
                    <Grid item xs={12}>
                        <Typography variant="h5" color="inherit">
                            {primary}
                        </Typography>
                    </Grid>
                </Grid>
            </CardContent>
            <Box
                sx={{
                    backgroundColor: colorBottom,
                    opacity: 0.8,
                    borderRadius: 1,
                    width: '100%',
                    p: 3,
                    mt: 2,
                    position: 'relative',
                    '&:hover': {
                        opacity: 0.3
                    }
                }}
            >
                <Link
                    component={RouterLink} // Make sure to import { Link as RouterLink } from 'react-router-dom'
                    to="#home"
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#fff',
                        textDecoration: 'none !important',
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        zIndex: 1,
                        '&:hover': {
                            textDecoration: 'none !important'
                        },
                        // Explicit border removal
                        border: 'none !important',
                        outline: 'none !important',
                        boxShadow: 'none !important'
                    }}
                >
                    <Typography
                        component="span" // Important for proper rendering inside Link
                        sx={{
                            mr: 1,
                            color: 'black',
                            // Complete border removal
                            border: '0 !important',
                            textDecoration: 'none !important',
                            '&:hover': {
                                border: '0 !important',
                                textDecoration: 'none !important'
                            },
                            // Remove any focus outlines
                            '&:focus': {
                                outline: 'none',
                                boxShadow: 'none'
                            }
                        }}
                    >
                        More Info
                    </Typography>
                    <Box
                        sx={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            backgroundColor: 'black',
                            borderRadius: '50%', // Makes it circular
                            width: 24, // Adjust size as needed
                            height: 24, // Should match width for perfect circle
                            p: 0.5 // Padding inside the circle
                        }}
                    >
                        <ArrowForward
                            fontSize="small"
                            sx={{
                                color: 'white',
                                fontSize: '1rem' // Adjust icon size if needed
                            }}
                        />
                    </Box>
                </Link>
            </Box>
        </Card>
    );
};

RevenueCard.propTypes = {
    primary: PropTypes.string,
    secondary: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    content: PropTypes.string,
    iconPrimary: PropTypes.oneOfType([
        PropTypes.element, // JSX element
        PropTypes.func // Component reference
    ]),
    color: PropTypes.string
};

RevenueCard.defaultProps = {
    color: '#5e35b1'
};

export default RevenueCard;
